CREATE TABLE mission_definitions (
 id UUID PRIMARY KEY, code VARCHAR(32) NOT NULL UNIQUE, version BIGINT NOT NULL CHECK(version>0),
 state VARCHAR(16) NOT NULL, draft TEXT NOT NULL, published_revision BIGINT, effective_from DATE, archived_from DATE
);
CREATE TABLE mission_revisions (
 definition_id UUID NOT NULL REFERENCES mission_definitions(id), revision BIGINT NOT NULL,
 config TEXT NOT NULL, effective_from DATE NOT NULL, legacy_code VARCHAR(32),
 target INTEGER NOT NULL CHECK(target>0), reward_xp INTEGER NOT NULL CHECK(reward_xp>=0),
 reward_gold INTEGER NOT NULL CHECK(reward_gold>=0), reward_gems INTEGER NOT NULL CHECK(reward_gems>=0),
 PRIMARY KEY(definition_id,revision)
);
CREATE FUNCTION mission_revision_immutable() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION 'Published mission revisions are immutable'; END $$;
CREATE TRIGGER mission_revision_immutable BEFORE UPDATE OR DELETE ON mission_revisions FOR EACH ROW EXECUTE FUNCTION mission_revision_immutable();
CREATE TABLE mission_periods (scope VARCHAR(16) NOT NULL, cadence VARCHAR(16) NOT NULL, period_start DATE NOT NULL, selection TEXT NOT NULL, PRIMARY KEY(scope,cadence,period_start));
CREATE TABLE mission_instances (
 id UUID PRIMARY KEY, owner_id UUID NOT NULL, scope VARCHAR(16) NOT NULL, definition_id UUID NOT NULL REFERENCES mission_definitions(id),
 revision BIGINT NOT NULL, period_start DATE NOT NULL, config TEXT NOT NULL, progress INTEGER NOT NULL DEFAULT 0 CHECK(progress>=0),
 legacy_source VARCHAR(128), UNIQUE(owner_id,definition_id,period_start), FOREIGN KEY(definition_id,revision) REFERENCES mission_revisions(definition_id,revision)
);
CREATE INDEX mission_instances_owner_idx ON mission_instances(owner_id,period_start);
CREATE TABLE mission_progress_events (
 instance_id UUID NOT NULL REFERENCES mission_instances(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 source_id VARCHAR(160) NOT NULL, amount INTEGER NOT NULL CHECK(amount>=0), occurred_at TIMESTAMPTZ NOT NULL,
 PRIMARY KEY(instance_id,user_id,source_id)
);
CREATE TABLE mission_claims (
 instance_id UUID NOT NULL REFERENCES mission_instances(id) ON DELETE CASCADE, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
 request_id VARCHAR(128) NOT NULL, claimed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
 PRIMARY KEY(instance_id,user_id), UNIQUE(user_id,request_id)
);
CREATE TABLE mission_admin_requests (actor_id UUID NOT NULL REFERENCES admin_accounts(id), request_id VARCHAR(128) NOT NULL, fingerprint TEXT NOT NULL, result TEXT NOT NULL, PRIMARY KEY(actor_id,request_id));
CREATE TABLE mission_contribution_events (
 source_id VARCHAR(160) NOT NULL, user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE, clan_id UUID NOT NULL REFERENCES clans(id) ON DELETE CASCADE,
 points INTEGER NOT NULL CHECK(points>=0), source_type VARCHAR(32) NOT NULL, PRIMARY KEY(source_id,user_id,source_type)
);
